export const ALL_CODES: Record<PbCodeTable, Record<string, string>> = { ...CODES, INVESTOR_TYPE, INVESTOR_STATUS };

/** Parent INDUSTRY code (first 4 chars) for a 6-char sub-industry code, else null. */
export function industryParent(code: string): string | null {
  const c = String(code);
  if (c.length === 6) return c.slice(0, 4);
  if (c.length === 4) return c.slice(0, 2);
  return null;
}

/**
 * Decode a code to its description. Never returns null: unknown codes are returned verbatim
 * and a warning is pushed onto `warnings` (if given).
 */
export function decodeCode(table: PbCodeTable, code: string | number | null | undefined, warnings?: string[]): string {
  if (code === null || code === undefined || code === "") return "";
  const key = String(code);
  const hit = ALL_CODES[table]?.[key];
  if (hit !== undefined) return hit;
  if (warnings) warnings.push(`unknown ${table} code: ${key}`);
  return key;
}
